options.afterRender:
window.exportCncCsv = function() {
  const table = document.querySelector('.cnc-table');
  if (!table) return;
  const rows = table.querySelectorAll('tr');
  const csvLines = [];
  rows.forEach(tr => {
    const cells = tr.querySelectorAll('th, td');
    const rowValues = [];
    cells.forEach(cell => {
      let val = cell.innerText.trim();
      val = val.replace(/"/g, '""');
      if (val.includes(',') || val.includes('"') || val.includes('\n')) {
        val = '"' + val + '"';
      }
      rowValues.push(val);
    });
    csvLines.push(rowValues.join(','));
  });

  const csvContent = "\uFEFF" + csvLines.join('\r\n');
  const blob = new Blob([csvContent], { type: 'text/csv;charset=utf-8;' });
  const url = URL.createObjectURL(blob);
  const link = document.createElement('a');

  const titleEl = document.querySelector('.cnc-title-text');
  const mName = titleEl ? titleEl.innerText.replace('Production Information-', '').trim() : 'Machine';
  const today = new Date().toISOString().slice(0, 10);

  link.setAttribute('href', url);
  link.setAttribute('download', 'Production_Information_' + mName + '_' + today + '.csv');
  document.body.appendChild(link);
  link.click();
  document.body.removeChild(link);
  URL.revokeObjectURL(url);
};
